<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import RecordDelete from './RecordDelete.vue'
import PendingDeployment from './PendingDeployment.vue'
import { api, beijingTime, durationText } from './api'
import { errorMessage, statusLabel, requestKey, jobName, type Job, type Settings, type Recovery } from './monitoring'
const page=ref(1),total=ref(0),checked=ref<Job[]>([]),deletion=ref<InstanceType<typeof RecordDelete>>()
const route=useRoute(),router=useRouter(),items=ref<Job[]>([]),job=ref<Job>(),logs=ref<{id:number;time:number;message:string}[]>([]),error=ref(''),busy=ref(false),actionBusy=ref(false),recovery=ref<Recovery>()
const stages=ref<{step:number;phase:string;host:string;title:string;status:string;message:string;time:number}[]>([]),search=ref(''),errorsOnly=ref(false),autoScroll=ref(true),logElement=ref<HTMLElement>()
const visibleLogs=computed(()=>logs.value.filter(log=>(!search.value||log.message.toLowerCase().includes(search.value.toLowerCase()))&&(!errorsOnly.value||/失败|错误|error|failed/i.test(log.message))))
const failedStage=computed(()=>stages.value.filter(s=>s.status==='失败').at(-1))
const confirming=ref(false),recoveryKind=ref(''),preview=ref<{token:string;revision:string;node?:string;scope:string;target_release:string;previous_release:string;message:string;changes:{field:string;effect:string}[]}>()
let disposed=false,cursor=0,generation=0,timer:ReturnType<typeof setInterval>|undefined
async function load(){if(disposed||document.hidden||busy.value)return;busy.value=true;const current=generation;try{const id=route.params.id;if(id){const result=await api<{job:Job;logs:typeof logs.value;cursor:number;stages:typeof stages.value}>(`/api/deployments/${encodeURIComponent(String(id))}?cursor=${cursor}`);if(current===generation&&!disposed){job.value=result.job;stages.value=result.stages||[];logs.value.push(...result.logs);if(logs.value.length>1000)logs.value.splice(0,logs.value.length-1000);cursor=result.cursor;await nextTick();if(autoScroll.value&&logElement.value)logElement.value.scrollTop=logElement.value.scrollHeight}}else{const [result,settings]=await Promise.all([api<{items:Job[];total:number}>(`/api/deployments?page=${page.value}`),api<Settings>('/api/settings')]);if(current===generation&&!disposed){items.value=result.items;total.value=result.total;recovery.value=settings.recovery;if(page.value>Math.max(1,Math.ceil(total.value/20))){page.value=Math.max(1,Math.ceil(total.value/20));generation++}}}if(current===generation&&!disposed)error.value=''}catch(e){if(current===generation&&!disposed)error.value=errorMessage(e)}finally{busy.value=false;if(!disposed&&current!==generation)void load()}}
async function action(kind:string){if(!job.value||actionBusy.value)return;actionBusy.value=true;error.value='';try{if(job.value.kind==='remove-nodes'){const next=await api<{id:string}>('/api/servers/remove/continue','POST',{job:job.value.id});await router.push(`/deployments/${next.id}`);return}if(job.value.kind==='migrate'){const settings=await api<Settings>('/api/settings');const next=await api<Job>('/api/deployments','POST',{request_key:requestKey(),revision:settings.revision,kind:'migrate',node:job.value.node});await router.push(`/deployments/${next.id}`);return}recoveryKind.value=kind;preview.value=await api(`/api/deployments/${job.value.id}/recovery-preview`,'POST',{kind});confirming.value=true}catch(e){error.value=errorMessage(e)}finally{actionBusy.value=false}}
async function executeRecovery(){if(!job.value||!preview.value||actionBusy.value)return;actionBusy.value=true;try{const next=await api<Job>('/api/deployments','POST',{request_key:requestKey(),revision:preview.value.revision,kind:recoveryKind.value,node:preview.value.node||'',original_job:job.value.id,recovery_token:preview.value.token});confirming.value=false;await router.push(`/deployments/${next.id}`)}catch(e){error.value=errorMessage(e);confirming.value=false}finally{actionBusy.value=false}}
watch(()=>route.fullPath,()=>{generation++;cursor=0;logs.value=[];stages.value=[];job.value=undefined;preview.value=undefined;confirming.value=false;void load()})
function visibility(){if(!document.hidden)void load()}
onMounted(()=>{void load();timer=setInterval(load,2000);document.addEventListener('visibilitychange',visibility)})
onUnmounted(()=>{disposed=true;generation++;clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
<template>
<el-alert v-if="error" :title="error" type="warning" :closable="false"/>
<template v-if="!route.params.id"><PendingDeployment :recovery="recovery"/><el-card shadow="never"><RecordDelete ref="deletion" :records="checked" label="部署任务历史" endpoint="/api/deployments/delete" @done="load"/><el-table :data="items" @selection-change="checked=$event" empty-text="暂无后台部署任务"><el-table-column type="selection" :selectable="(row:Job)=>!!row.can_delete" width="48"/><el-table-column label="任务" min-width="200"><template #default="{row}"><router-link :to="`/deployments/${row.id}`">{{jobName(row.kind)}} · {{row.node||'主服务器 / 配置范围'}}</router-link></template></el-table-column><el-table-column label="状态"><template #default="{row}">{{statusLabel(row.status)}}</template></el-table-column><el-table-column label="开始时间" min-width="190"><template #default="{row}">{{beijingTime(row.created)}}</template></el-table-column><el-table-column prop="message" label="结果" min-width="220"/><el-table-column label="操作与保护" min-width="220"><template #default="{row}"><el-button v-if="row.can_resume||row.can_rollback" link type="primary" @click="router.push(`/deployments/${row.id}`)">继续 / 回退</el-button><el-button link type="danger" :disabled="!row.can_delete" @click="deletion?.open([row])">删除</el-button><small class="muted">{{row.delete_reason}}</small></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @change="checked=[];generation++;load()"/></el-card></template>
<template v-else><el-card shadow="never"><h3>{{jobName(job?.kind||'')}} · {{statusLabel(job?.status||'queued')}}</h3><p>范围：{{job?.scope||'正在读取'}} · 开始：{{job?.created?beijingTime(job.created):'未知'}} · 持续：{{job?.created?durationText((['running','queued'].includes(job.status)?Date.now()/1000:job.updated)-job.created):'未知'}}</p><p>{{job?.message||'任务在宿主机执行，关闭页面不会终止。后台重启后自动重新连接。'}}</p><el-alert v-if="failedStage" :title="`${failedStage.host}：${failedStage.title}`" :description="failedStage.message" type="error" :closable="false"/><p v-if="job?.parent_id">原任务：<router-link :to="`/deployments/${job.parent_id}`">查看原任务 →</router-link></p><div class="filters"><el-button @click="router.push('/deployments')">返回任务列表</el-button><el-button v-if="job?.can_resume" type="primary" :loading="actionBusy" @click="action('resume')">继续原任务</el-button><el-button v-if="job?.can_rollback" :loading="actionBusy" @click="action('rollback')">查看回退影响</el-button><span v-if="job && !job.can_resume&&!job.can_rollback" class="muted">{{job.recovery_reason}}</span></div></el-card>
<el-card shadow="never"><h3>部署阶段</h3><el-table v-if="stages.length" :data="stages"><el-table-column prop="step" label="步骤" width="70"/><el-table-column prop="title" label="阶段" min-width="230"/><el-table-column prop="host" label="服务器" min-width="160"/><el-table-column prop="status" label="状态" width="90"/></el-table><p v-else class="muted">{{job&&['failed','complete','interrupted'].includes(job.status)?'此任务没有结构化阶段记录，请查看原始日志。':'正在等待阶段事件；仅展示实际执行的步骤。'}}</p></el-card>
<el-card shadow="never"><div class="card-heading"><h3>执行日志</h3><a v-if="job&&job.id!=='current'" :href="`/api/deployments/${job.id}/logs/download`">下载脱敏日志</a></div><div class="filters"><el-input v-model="search" clearable placeholder="搜索日志"/><el-checkbox v-model="errorsOnly">仅看错误</el-checkbox><el-checkbox v-model="autoScroll">自动滚动</el-checkbox></div><p class="muted">页面保留最近 1000 条日志，完整记录可下载。</p><pre ref="logElement" class="task-log">{{visibleLogs.map(log=>log.message).join('')||'暂无符合条件的日志'}}</pre></el-card></template>
<el-dialog v-model="confirming" :title="recoveryKind==='resume'?'继续原任务':'确认回退范围'" width="min(680px,96vw)" :close-on-click-modal="false"><template v-if="preview"><p>操作范围：{{preview.scope}}</p><p>原任务版本：{{preview.target_release||'未知'}}；回退参考版本：{{preview.previous_release||'未知'}}</p><p>{{preview.message}}</p><el-table v-if="preview.changes.length" :data="preview.changes"><el-table-column prop="field" label="涉及配置"/><el-table-column prop="effect" label="说明"/></el-table><p class="muted">预览 10 分钟有效，配置或部署状态变化后必须重新预览。</p></template><template #footer><el-button @click="confirming=false">取消</el-button><el-button type="primary" :loading="actionBusy" @click="executeRecovery">{{recoveryKind==='resume'?'确认继续':'确认回退'}}</el-button></template></el-dialog>
</template>
<style scoped>.task-log{white-space:pre-wrap;overflow-wrap:anywhere;background:#112038;color:#dae6fa;padding:20px;border-radius:8px;max-height:65vh;overflow:auto;font:13px/1.7 monospace}</style>
